function gerarSenha(t,e,n,c){let o="abcdefghijklmnopqrstuvwxyz";if(e&&(o+="0123456789"),n&&(o+="ABCDEFGHIJKLMNOPQRSTUVWXYZ"),c&&(o+="!@#$%^&*()_+"),!o)return null;let a="";for(let e=0;e<t;e++)a+=o.charAt(Math.floor(Math.random()*o.length));return a}document.getElementById("botao-gerar").addEventListener("click",function(){var e=document.getElementById("comprimento-senha").value,t=document.getElementById("incluir-numeros").checked,n=document.getElementById("incluir-maiusculas").checked,c=document.getElementById("incluir-especiais").checked,e=gerarSenha(Math.min(e,12),t,n,c);document.getElementById("senha-gerada").textContent=e||"Selecione pelo menos uma opção."});